function shoot(kind) {
  const def = WEAPON_DEFS[kind];
  if (inventory.mag[kind] <= 0) { tryReload(kind); return; }
  inventory.mag[kind]--;
  hitCooldown = def.cooldown; recoilT = 0.16; muzzleT = 0.055;
  audio.gunshot(kind); game.shake(0.09);
  // compute ray from camera
  const origin = camera.getWorldPosition(new THREE.Vector3());
  const dir = camera.getWorldDirection(new THREE.Vector3());
  dir.x += (Math.random()-0.5)*def.spread; ...
  dir.normalize();
  // nearest target NPC/node/wall within range
  const hit = raycastTargets(origin, dir, def.range);
  const end = hit ? hit.point : origin.clone().addScaledVector(dir, def.range);
  fx.tracer(origin.clone().addScaledVector(dir,0.5), end, def.tracer);
  if (hit?.type==='npc') { game.hitNPC(...); fx.bloodBurst(...); }
  else if (hit?.type==='node') game.hitNode(hit.obj, def.damage*0.3, kind);
  else if (hit) fx.spark(...);
  // recoil pitch kick
  pitch = clamp(pitch + 0.012, ...); // upward
  if (inventory.mag[kind]===0) tryReload(kind);
}
