301: function nearestTarget(maxDist = 1.65) {
302:   const p = player.group.position;
303:   let best = null, bestScore = Infinity;
304:   const consider = (obj, point, type) => {
305:     const dx = point.x - p.x, dz = point.z - p.z;
306:     const dist = Math.hypot(dx, dz);
307:     if (dist > maxDist) return;
308:     const dot = (dx * player.forward.x + dz * player.forward.z) / Math.max(dist, 0.001);
309:     if (dot < -0.25) return;
310:     const score = dist + (dot < 0.15 ? 0.55 : 0);
311:     if (score < bestScore) { best = { obj, type, dist }; bestScore = score; }
312:   };
313:   for (const npc of npcs) if (npc.alive && npc.state !== 'grabbed') consider(npc, npc.group.position, 'npc');
314:   for (const weapon of weapons) if (weapon.state === 'ground' && (mode === 'sandbox' || weapon.island === currentIsland)) consider(weapon, weapon.group.position, 'weapon');
315:   for (const node of resourceNodes) if (node.active && (mode === 'sandbox' || node.island === currentIsland)) consider(node, node.group.position, 'resource');
316:   return best;
317: }
